## Example 1: `pair_36fbc6627ac4d575`

建议在Grid下使用LazyForEach时设置合理的cacheCount

### Triggering pattern

```arkts
// 文件：ImageGallery.ets
@Entry
@Component
struct ImageGallery {
  private imageList: string[] = [];

  aboutToAppear() {
    for (let i = 1; i <= 500; i++) {
      this.imageList.push('image_' + i + '.png');
    }
  }

  build() {
    Column() {
      Grid() {
        LazyForEach(this.imageList, (image: string) => {
          GridItem() {
            Image($r('app.media.' + image))
              .width(100)
              .height(100)
          }
        }, (image: string) => image)
      }
      // 未设置缓存数量
      .columnsTemplate('1fr 1fr 1fr 1fr')
      .columnsGap(5)
      .rowsGap(5)
      .height('100%')
    }
  }
}
```

### Repair pattern

```arkts
// 文件：ImageGallery.ets
@Entry
@Component
struct ImageGallery {
  private imageList: string[] = [];

  aboutToAppear() {
    for (let i = 1; i <= 500; i++) {
      this.imageList.push('image_' + i + '.png');
    }
  }

  build() {
    Column() {
      Grid() {
        LazyForEach(this.imageList, (image: string) => {
          GridItem() {
            Image($r('app.media.' + image))
              .width(100)
              .height(100)
          }
        }, (image: string) => image)
      }
      // 设置缓存数量
      .cachedCount(4)
      .columnsTemplate('1fr 1fr 1fr 1fr')
      .columnsGap(5)
      .rowsGap(5)
      .height('100%')
    }
  }
}
```

### Rationale

由于图片库中包含大量图片，未设置 cachedCount 可能导致滚动时图片加载不及时。通过设置 cachedCount(4)，Grid 会预先缓存 4 个 GridItem，提升图片加载和滚动的性能。

